// scraper.py prints exactly one JSON document on stdout -- success, failure or
// skipped tick. Anything else means the command itself broke.
const out = [];

for (const item of $input.all()) {
  const stdout = (item.json.stdout || '').trim();
  const stderr = (item.json.stderr || '').trim();

  let parsed;
  try {
    parsed = JSON.parse(stdout.slice(stdout.indexOf('{')));
  } catch (e) {
    out.push({ json: { ok: false, skipped: false, error: 'unparseable scraper output: ' + e.message, stdout: stdout.slice(0, 2000), stderrTail: stderr.slice(-2000) } });
    continue;
  }

  parsed.skipped = parsed.skipped === true;
  parsed.stderrTail = stderr.slice(-2000);
  out.push({ json: parsed });
}

return out;

// One item per company, each carrying its own MCP dump. No dedup by design:
// every run emits the full current snapshot so downstream nodes can diff.
const out = [];

for (const item of $input.all()) {
  const d = item.json;
  const bySymbol = Object.fromEntries((d.mcp || []).map(m => [m.symbol, m]));

  const rows = [
    ...(d.resultCalendar || []).map(r => ({ ...r, section: 'resultCalendar' })),
    ...(d.rapidResults || []).map(r => ({ ...r, section: 'rapidResults' })),
  ];

  for (const row of rows) {
    const mcp = row.nseSymbol ? bySymbol[row.nseSymbol] : undefined;
    out.push({
      json: {
        scrapedAt: d.scrapedAt,
        calendarDate: d.calendarDate,
        cacheEnabled: d.cacheEnabled,
        section: row.section,
        company: row.company,
        scId: row.scId,
        nseSymbol: row.nseSymbol || null,
        exchange: row.exchange,
        ltp: row.ltp,
        changePercent: row.changePercent,
        resultType: row.resultType || row.period || null,
        record: row,
        mcpOk: mcp ? mcp.ok : null,
        mcpCounts: mcp && mcp.data ? mcp.data.counts : null,
        mcp: mcp || null,
      },
    });
  }
}

return out;
